def read_publisher(rec):
    fields = (
        rec.get_fields('260')
        or rec.get_fields('264')[:1]
        or [rec.get_linkage('260', '880')]
    )
    if not fields:
        return
    publisher = []
    publish_places = []
    for f in fields:
